// Test file: src/app/routes/article/article.mapper.test.ts

import { articleMapper } from './article.mapper';
// Adjust imports based on your actual mapper implementation

describe('Article Mapper - readingTime field handling', () => {

  describe('mapping article with readingTime', () => {
    it('should correctly map article with readingTime field', () => {
      const articleData = {
        id: 1,
        title: 'Test Article',
        body: 'This is a test article body with some content.',
        readingTime: 1,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped).toHaveProperty('readingTime');
      expect(mapped.readingTime).toBe(1);
    });

    it('should handle article with minimum readingTime value of 1', () => {
      const articleData = {
        id: 2,
        title: 'Short Article',
        body: 'Short content',
        readingTime: 1,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped.readingTime).toBe(1);
      expect(mapped.readingTime).toBeGreaterThanOrEqual(1);
    });

    it('should handle article with calculated readingTime for longer content', () => {
      const longBody = 'word '.repeat(250); // 250 words
      const articleData = {
        id: 3,
        title: 'Long Article',
        body: longBody,
        readingTime: 2, // Math.ceil(250/200) = 2
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped.readingTime).toBe(2);
      expect(typeof mapped.readingTime).toBe('number');
      expect(Number.isInteger(mapped.readingTime)).toBe(true);
    });

    it('should ensure readingTime is always an integer', () => {
      const articleData = {
        id: 4,
        title: 'Article',
        body: 'word '.repeat(401), // 401 words -> Math.ceil(401/200) = 3
        readingTime: 3,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(Number.isInteger(mapped.readingTime)).toBe(true);
      expect(mapped.readingTime).toBe(3);
    });

    it('should handle article with empty body having readingTime of 1', () => {
      const articleData = {
        id: 5,
        title: 'Empty Article',
        body: '',
        readingTime: 1,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped.readingTime).toBe(1);
    });

    it('should preserve readingTime when mapping article response', () => {
      const articleData = {
        id: 6,
        title: 'Test',
        body: 'word '.repeat(500), // 500 words -> Math.ceil(500/200) = 3
        readingTime: 3,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped).toHaveProperty('readingTime');
      expect(mapped.readingTime).toBeDefined();
      expect(mapped.readingTime).not.toBeNull();
    });
  });

  describe('edge cases for readingTime mapping', () => {
    it('should handle articles with large readingTime values', () => {
      const articleData = {
        id: 7,
        title: 'Very Long Article',
        body: 'A'.repeat(100000), // 100000 words -> Math.ceil(100000/200) = 500
        readingTime: 500,
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped.readingTime).toBe(500);
      expect(typeof mapped.readingTime).toBe('number');
    });

    it('should not allow readingTime to be zero', () => {
      const articleData = {
        id: 8,
        title: 'Article',
        body: 'Some content',
        readingTime: 1, // Should never be 0
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(mapped.readingTime).not.toBe(0);
      expect(mapped.readingTime).toBeGreaterThanOrEqual(1);
    });

    it('should not allow decimal readingTime values', () => {
      const articleData = {
        id: 9,
        title: 'Article',
        body: 'word '.repeat(300), // 300 words -> Math.ceil(300/200) = 2
        readingTime: 2, // Should be integer, not 1.5
        // ... other article fields
      };

      const mapped = articleMapper(articleData);

      expect(Number.isInteger(mapped.readingTime)).toBe(true);
      expect(mapped.readingTime % 1).toBe(0);
    });
  });
});

